/**
 * The persistent 236px sidebar: brand, the add-session action, the session
 * list, and the standing links pinned to the bottom above the memory-only
 * notice (WP-D). Below `md` it is rendered inside a drawer instead of beside
 * the content; the markup is the same either way.
 */

import { NavLink, useNavigate } from 'react-router'
import { useTranslation } from 'react-i18next'

import { useSessions } from '../state/sessions-context'
import { Button } from '../ui/Button'
import { ClockIcon, PlusIcon, ShieldCheckIcon } from '../ui/Icon'
import { Eyebrow } from '../ui/Sheet'
import { SessionRow } from './SessionRow'
import { ROUTES } from './routes'

export function SidebarBrand() {
  const { t } = useTranslation()
  return (
    <span className="flex items-center gap-[9px]">
      <ClockIcon size={18} className="text-primary" />
      <span className="text-[14px] font-semibold tracking-[-0.02em]">{t('app.name')}</span>
    </span>
  )
}

export function Sidebar({ onNavigate }: { onNavigate?: () => void }) {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const { state, select } = useSessions()

  function openSession(id: string) {
    select(id)
    void navigate(ROUTES.home)
    onNavigate?.()
  }

  function addSession() {
    // Deselecting is what returns the main pane to the upload screen; the
    // session stays in the list.
    select(null)
    void navigate(ROUTES.home)
    onNavigate?.()
  }

  return (
    <div className="flex h-full min-h-0 flex-col bg-surface">
      <div className="hidden h-[52px] shrink-0 items-center border-b border-line-soft px-4 md:flex">
        <SidebarBrand />
      </div>

      <div className="p-3">
        <Button variant="primary" className="w-full" onClick={addSession}>
          <PlusIcon size={14} />
          {t('nav.addSession')}
        </Button>
      </div>

      <div className="flex min-h-0 flex-1 flex-col px-3">
        <div className="flex items-center justify-between px-[10px] pt-1.5 pb-2">
          <Eyebrow>{t('nav.sessions')}</Eyebrow>
          <span className="font-mono text-[10.5px] text-slate-400">{state.sessions.length}</span>
        </div>

        {state.sessions.length === 0 ? (
          <p className="rounded-[6px] border border-dashed border-[#E1E8F0] px-[10px] py-4 text-center text-[11px] leading-[1.5] text-slate-500">
            {t('nav.sessionsEmpty')}
          </p>
        ) : (
          <ul
            className="flex min-h-0 flex-1 flex-col gap-[3px] overflow-y-auto"
            aria-label={t('nav.sessionList')}
          >
            {state.sessions.map((entry) => (
              <SessionRow
                key={entry.id}
                entry={entry}
                active={entry.id === state.selectedId}
                onSelect={() => openSession(entry.id)}
              />
            ))}
          </ul>
        )}
      </div>

      <div className="mt-auto flex flex-col gap-0.5 border-t border-line-soft p-3">
        <p className="flex items-center gap-[7px] px-[10px] pb-2 text-[11px] leading-[1.5] text-slate-500">
          <ShieldCheckIcon size={13} className="shrink-0 text-green" />
          {t('nav.memoryOnly')}
        </p>
        <NavItem to={ROUTES.findLogs} onNavigate={onNavigate}>
          {t('nav.findLogs')}
        </NavItem>
        <NavItem to={ROUTES.dataPolicy} onNavigate={onNavigate}>
          {t('nav.dataPolicy')}
        </NavItem>
        <NavItem to={ROUTES.about} onNavigate={onNavigate}>
          {t('nav.about')}
        </NavItem>
      </div>
    </div>
  )
}

function NavItem({
  to,
  children,
  onNavigate,
}: {
  to: string
  children: React.ReactNode
  onNavigate?: () => void
}) {
  return (
    <NavLink
      to={to}
      onClick={onNavigate}
      className={({ isActive }) =>
        `flex h-[30px] items-center rounded-[6px] px-[10px] text-[12.5px] transition-colors ${
          isActive ? 'bg-primary-tint font-medium text-primary' : 'text-ink-2 hover:bg-ground'
        }`
      }
    >
      {children}
    </NavLink>
  )
}
=== SessionRow ===
/**
 * One row in the sidebar's session list. There is no separate history table —
 * the sidebar is the history (WP-D), so a row has to carry the whole summary:
 * which session, which project, the verdict, and — while it is running — its
 * progress.
 *
 * The active row is tinted rather than given a left accent bar, so the list
 * stays a flat column of equal-width rows at any translation length.
 */

import { useTranslation } from 'react-i18next'

import { useFormatters } from '../i18n/formatters'
import type { SessionEntry } from '../state/session-store'
import { headlineVerdict, progressRatio, projectLabel, shortSessionId } from './session-display'

export function SessionRow({
  entry,
  active,
  onSelect,
}: {
  entry: SessionEntry
  active: boolean
  onSelect: () => void
}) {
  const { t } = useTranslation()
  const fmt = useFormatters()

  const ratio = progressRatio(entry)
  const verdict = headlineVerdict(entry)
  const project = projectLabel(entry)
  const analyzing = entry.status.phase === 'analyzing'

  return (
    <li>
      <button
        type="button"
        onClick={onSelect}
        aria-current={active ? 'true' : undefined}
        className={`flex w-full flex-col gap-1 rounded-[6px] px-[10px] py-2 text-left transition-colors ${
          active ? 'bg-primary-tint' : 'hover:bg-ground'
        }`}
      >
        <span className="flex items-baseline justify-between gap-2">
          <span
            className={`truncate font-mono text-[12.5px] ${
              active ? 'font-medium text-primary' : 'text-ink'
            }`}
          >
            {shortSessionId(entry)}
          </span>
          <span className="shrink-0 font-mono text-[10.5px] font-semibold">
            {analyzing ? (
              <span className={active ? 'text-primary' : 'text-slate-500'}>
                {ratio === null ? '' : fmt.percent(ratio)}
              </span>
            ) : verdict ? (
              <span className="text-green">{fmt.currency(verdict.savingsUsd)}</span>
            ) : (
              <StatusMark entry={entry} />
            )}
          </span>
        </span>

        {analyzing ? (
          <span
            className="block h-[3px] overflow-hidden rounded-[2px] bg-[#D6E3FB]"
            role="progressbar"
            aria-label={t('status.analyzing')}
            aria-valuenow={ratio === null ? undefined : Math.round(ratio * 100)}
            aria-valuemin={0}
            aria-valuemax={100}
          >
            <span
              className="block h-full bg-primary transition-[width] duration-200"
              style={{ width: `${(ratio ?? 0) * 100}%` }}
            />
          </span>
        ) : (
          <span className="flex items-baseline justify-between gap-2">
            <span
              className={`truncate font-mono text-[10.5px] ${
                active ? 'text-[#6B87B8]' : 'text-slate-400'
              }`}
            >
              {project ?? entry.fileName}
            </span>
            {verdict && (
              <span
                className={`shrink-0 font-mono text-[10.5px] ${
                  active ? 'text-primary' : 'text-slate-500'
                }`}
              >
                {verdict.ttl}
              </span>
            )}
          </span>
        )}
      </button>
    </li>
  )
}

/**
 * What the money column shows when there is no saving to show. The column is
 * about 40px wide, so a state is a mark plus a screen-reader label rather than
 * a word no translation would fit.
 */
function StatusMark({ entry }: { entry: SessionEntry }) {
  const { t } = useTranslation()
  switch (entry.status.phase) {
    case 'rejected':
      return <Mark symbol="!" tone="text-red" label={t('rejected.title')} />
    case 'failed':
      return <Mark symbol="!" tone="text-red" label={t('status.failed')} />
    case 'cancelled':
      return <Mark symbol="—" tone="text-slate-400" label={t('status.cancelled')} />
    default:
      return null
  }
}

function Mark({ symbol, tone, label }: { symbol: string; tone: string; label: string }) {
  return (
    <span className={tone}>
      <span aria-hidden="true">{symbol}</span>
      <span className="sr-only">{label}</span>
    </span>
  )
}
=== pages/AnalyzePage ===
/**
 * The main pane. Which of the five states it shows is a function of the
 * selected session's status alone — there is no separate screen-level state to
 * drift out of sync with the worker.
 *
 * Nothing selected is the upload screen, which is also the landing page.
 */

import { useNavigate } from 'react-router'
import { useTranslation } from 'react-i18next'

import { useFormatters } from '../../i18n/formatters'
import { useSessions } from '../../state/sessions-context'
import { MainPane, TopBar } from '../Shell'
import { AnalyzingPanel } from '../analysis/AnalyzingPanel'
import { RejectionPanel } from '../analysis/RejectionPanel'
import { ResultPlaceholder } from '../analysis/ResultPlaceholder'
import { CancelledPanel, FailurePanel } from '../analysis/StatusPanel'
import { ROUTES } from '../routes'
import { sessionTitle, shortSessionId } from '../session-display'
import { UploadScreen } from './UploadScreen'

export function AnalyzePage() {
  const { t } = useTranslation()
  const fmt = useFormatters()
  const navigate = useNavigate()
  const { selected } = useSessions()

  if (!selected) {
    return (
      <>
        <TopBar title={t('app.title')} />
        <MainPane>
          <UploadScreen onWhereAreLogs={() => void navigate(ROUTES.findLogs)} />
        </MainPane>
      </>
    )
  }

  const title =
    selected.status.phase === 'analyzing'
      ? t('analyzing.title')
      : (sessionTitle(selected) ?? shortSessionId(selected))

  return (
    <>
      <TopBar
        title={title}
        meta={t('analyzing.fileMeta', {
          name: selected.fileName,
          size: fmt.bytes(selected.fileSizeBytes),
        })}
      />
      <MainPane>
        {selected.status.phase === 'analyzing' && <AnalyzingPanel entry={selected} />}
        {selected.status.phase === 'rejected' && <RejectionPanel entry={selected} />}
        {selected.status.phase === 'cancelled' && <CancelledPanel />}
        {selected.status.phase === 'failed' && <FailurePanel code={selected.status.code} />}
        {selected.status.phase === 'complete' && (
          <ResultPlaceholder result={selected.status.result} />
        )}
      </MainPane>
    </>
  )
}
